//! Code-plan §7.5 mechanism 1: `notary-cards` must reproduce the TypeScript verifier's verdict and code on every case in
//! `notary/vectors/cards/cases.json` (generated by `gen-notary-conformance.ts`), and every check in `coverage.json`
//! must have an accepting and a rejecting case (mechanism 3).
use notary_cards::{check_contributor, ContributorConfig, ContributorResult, World};
use notary_types::b64u;
use serde_json::{json, Value};

fn load(name: &str) -> Value {
    let p = std::path::PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../../vectors/cards").join(name);
    serde_json::from_str(&std::fs::read_to_string(p).expect("run gen-notary-conformance.ts")).unwrap()
}

#[test]
fn rust_agrees_with_typescript_on_every_case() {
    let file = load("cases.json");
    let cases = file["cases"].as_array().unwrap();
    assert!(cases.len() >= 58, "{} cases", cases.len());
    let mut disagreements = vec![];
    for c in cases {
        let world = World::from_json(&c["world"]).expect("world");
        let cfg = &c["config"];
        let trusted: Vec<String> = cfg["trustedRoots"].as_array().unwrap().iter().map(|x| x.as_str().unwrap().to_string()).collect();
        let now = notary_types::formats::parse_timestamp(cfg["nowIso"].as_str().unwrap()).unwrap();
        let config = ContributorConfig {
            trusted_roots: &trusted,
            app_certification_root: cfg["appCertificationRoot"].as_str().unwrap(),
            login_service_root: cfg["loginServiceCertificationRoot"].as_str().unwrap(),
            now_ms: now,
            max_chain_depth: cfg.get("maxChainDepth").and_then(Value::as_u64).unwrap_or(64) as usize,
        };
        let got = match check_contributor(&world, &c["input"], &c["predicate"], c["parameters"].as_object().unwrap(), &config) {
            ContributorResult::Ok { root_key_hash, chain_addresses } => json!({ "ok": true, "root_key_hash": b64u::encode(&root_key_hash), "chain_addresses": chain_addresses }),
            ContributorResult::Err { code, .. } => json!({ "ok": false, "code": code }),
        };
        if got != c["expect"] {
            disagreements.push(format!("{}: TypeScript {} / Rust {}", c["id"], c["expect"], got));
        }
    }
    assert!(disagreements.is_empty(), "{} disagreement(s):\n{}", disagreements.len(), disagreements.join("\n"));
}

#[test]
fn every_ported_check_has_accepting_and_rejecting_cases() {
    let cov = load("coverage.json");
    let ids: Vec<String> = load("cases.json")["cases"].as_array().unwrap().iter().map(|c| c["id"].as_str().unwrap().to_string()).collect();
    let checks = cov["checks"].as_object().unwrap();
    assert!(checks.len() >= 30);
    for (name, v) in checks {
        let accept = v["accept"].as_array().unwrap();
        let reject = v["reject"].as_array().unwrap();
        assert!(!accept.is_empty(), "{name}: no accepting case");
        assert!(name == "root_key" || !reject.is_empty(), "{name}: no rejecting case");
        for id in accept.iter().chain(reject) {
            assert!(ids.contains(&id.as_str().unwrap().to_string()), "{name}: unknown case {id}");
        }
    }
}
